{"content": """"Average delivery turnaround time (hours) per carrier on delivered orders."""
import csv
from collections import defaultdict
from datetime import datetime

def parse_dt(s):
    s = s.strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized date format: {s!r}")

stats = defaultdict(list)

with open("bookstore_orders.csv", newline="") as f:
    for r in csv.DictReader(f):
        if r["fulfillment_status"] != "Delivered":
            continue
        hours = (parse_dt(r["actual_delivery_date"]) - parse_dt(r["order_timestamp"])).total_seconds() / 3600
        stats[r["carrier_name"]].append(hours)

