                    d += 1; j += 2
                elif src[j] == '*' and j + 1 < n and src[j+1] == '/':
                    d -= 1; j += 2
                else:
                    j += 1
            i = j
            continue
        if c == '"':
            state = 'string'
        out.append(c); i += 1
    elif state == 'string':
        if c == '\\':
            out.append(src[i:i+2]); i += 2; continue
        if c == '"':
            state = 'code'
        out.append(c); i += 1
open(path, 'w').write(''.join(out))
print("done")
